package com.ias.approval;

import org.junit.jupiter.api.Test;
import java.util.*;
import static com.ias.approval.FeeApproval.*;
import static org.junit.jupiter.api.Assertions.*;

class FeeApprovalTest {
    Basis basis(boolean paid,boolean finance){return new Basis(1,3,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,2,0,1200,1300,1400,1400,200000,"RULE_1",finance,finance,paid,"a".repeat(64),"b".repeat(64));}
    Confirmation confirmation(Basis b){return new Confirmation(UUID.randomUUID(),b.quoteId(),b.quoteVersion(),b.quoteDigest(),b.companyId());}
    Facts facts(Basis b,Confirmation c){return new Facts(b,c,true,true,true,true,true,true,true);}
    Command command(UUID id,Action action,long version,Basis b){return new Command(UUID.randomUUID(),id,action,version,b,"justification");}
    Application submit(Basis b,Confirmation c){return apply(null,new Actor(1,2),command(UUID.randomUUID(),Action.SUBMIT,0,b),facts(b,c));}
    @Test void paidWaitsForCustomerAndCannotBeInternallyDecided(){var b=basis(true,false);var a=submit(b,null);assertEquals(State.WAITING_CUSTOMER,a.state());assertEquals(409,assertThrows(ApprovalFailure.class,()->apply(a,new Actor(1,4),command(a.id(),Action.APPROVE,1,b),facts(b,null))).status());}
    @Test void customerConfirmationCreatesTaskButIsNotSupervisorApproval(){var b=basis(true,false);var a=submit(b,null);a=apply(a,new Actor(1,2),command(a.id(),Action.REFRESH,1,b),facts(b,confirmation(b)));assertEquals(State.PENDING_SUPERVISOR,a.state());assertNull(a.supervisorId());assertEquals(2,a.version());}
    @Test void independentSupervisorThenFinanceCompleteFrozenBranch(){var b=basis(true,true);var c=confirmation(b);var a=submit(b,c);a=apply(a,new Actor(1,4),command(a.id(),Action.APPROVE,1,b),facts(b,c));assertEquals(State.WAITING_FINANCE,a.state());assertEquals(4L,a.supervisorId());a=apply(a,new Actor(1,5),command(a.id(),Action.APPROVE,2,b),facts(b,c));assertEquals(State.COMPLETED,a.state());assertEquals(5L,a.financeId());}
    @Test void selfApprovalAndMissingCurrentQualificationsFail(){var b=basis(false,false);var a=submit(b,null);assertEquals(403,assertThrows(ApprovalFailure.class,()->apply(a,new Actor(1,2),command(a.id(),Action.APPROVE,1,b),facts(b,null))).status());var f=new Facts(b,null,true,true,true,true,true,false,false);assertEquals(403,assertThrows(ApprovalFailure.class,()->apply(a,new Actor(1,4),command(a.id(),Action.APPROVE,1,b),f)).status());}
    @Test void missingSupervisorOrFinanceWaitsConfiguration(){var b=basis(false,true);var cmd=command(UUID.randomUUID(),Action.SUBMIT,0,b);var f=new Facts(b,null,true,true,true,false,false,true,true);var a=apply(null,new Actor(1,2),cmd,f);assertEquals(State.WAITING_CONFIGURATION,a.state());a=apply(a,new Actor(1,2),command(a.id(),Action.REFRESH,1,b),facts(b,null));a=apply(a,new Actor(1,4),command(a.id(),Action.APPROVE,2,b),new Facts(b,null,true,true,true,true,false,true,true));assertEquals(State.WAITING_CONFIGURATION,a.state());assertEquals(4L,a.supervisorId());a=apply(a,new Actor(1,2),command(a.id(),Action.REFRESH,3,b),facts(b,null));assertEquals(State.WAITING_FINANCE,a.state());}
    @Test void forgedTotalsAndLoweredPermanentBranchAreInvalid(){var b=basis(false,true);assertThrows(ApprovalFailure.class,()->new Basis(1,3,b.ticketId(),b.roundId(),b.faultRelationId(),b.groupId(),b.quoteId(),1,2,0,1,2,3,1,200000,"v",false,false,false,"a".repeat(64),"b".repeat(64)));assertThrows(ApprovalFailure.class,()->new Basis(1,3,b.ticketId(),b.roundId(),b.faultRelationId(),b.groupId(),b.quoteId(),1,2,0,1,2,3,3,200000,"v",true,false,false,"a".repeat(64),"b".repeat(64)));}
    @Test void staleQuoteMissingAckAndWrongConfirmationFailClosed(){var b=basis(true,false);var cmd=command(UUID.randomUUID(),Action.SUBMIT,0,b);assertThrows(ApprovalFailure.class,()->apply(null,new Actor(1,2),cmd,new Facts(b,null,false,true,true,true,true,true,true)));assertThrows(ApprovalFailure.class,()->apply(null,new Actor(1,2),cmd,new Facts(b,null,true,false,true,true,true,true,true)));assertThrows(ApprovalFailure.class,()->apply(null,new Actor(1,2),cmd,facts(b,new Confirmation(UUID.randomUUID(),UUID.randomUUID(),1,b.quoteDigest(),3))));}
    @Test void rejectionReasonAndTerminalHistoryAreEnforced(){var b=basis(false,false);var a=submit(b,null);assertThrows(ApprovalFailure.class,()->apply(a,new Actor(1,4),new Command(UUID.randomUUID(),a.id(),Action.REJECT,1,b," "),facts(b,null)));var rejected=apply(a,new Actor(1,4),command(a.id(),Action.REJECT,1,b),facts(b,null));assertEquals(State.REJECTED,rejected.state());assertThrows(ApprovalFailure.class,()->apply(rejected,new Actor(1,2),command(rejected.id(),Action.WITHDRAW,2,b),facts(b,null)));}
    @Test void onlyApplicantWithdrawsAndVersionIsMandatory(){var b=basis(true,false);var a=submit(b,null);assertThrows(ApprovalFailure.class,()->apply(a,new Actor(1,4),command(a.id(),Action.WITHDRAW,1,b),facts(b,null)));assertThrows(ApprovalFailure.class,()->apply(a,new Actor(1,2),command(a.id(),Action.WITHDRAW,0,b),facts(b,null)));assertEquals(State.WITHDRAWN,apply(a,new Actor(1,2),command(a.id(),Action.WITHDRAW,1,b),facts(b,null)).state());}
}
